-- Migration 022 (Postgres): SharePoint inbound invoice intake

CREATE TABLE IF NOT EXISTS "AP_INBOUND_SHAREPOINT" (
  "InboundSharePointId" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "DriveItemId" TEXT NOT NULL,
  "FileName" VARCHAR(500) NULL,
  "FolderPath" VARCHAR(1000) NULL,
  "MimeType" VARCHAR(150) NULL,
  "FileSizeBytes" BIGINT NULL,
  "WebUrl" VARCHAR(2000) NULL,
  "LastModifiedAt" TIMESTAMP NULL,
  "SiteId" VARCHAR(255) NULL,
  "DriveId" VARCHAR(255) NULL,
  "Status" VARCHAR(40) NOT NULL DEFAULT 'QUEUED',
  "DocumentId" BIGINT NULL,
  "ErrorMessage" TEXT NULL,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "UpdatedAt" TIMESTAMP NULL,
  CONSTRAINT "PK_AP_INBOUND_SHAREPOINT" PRIMARY KEY ("InboundSharePointId"),
  CONSTRAINT "UQ_AP_INBOUND_SHAREPOINT_DriveItemId" UNIQUE ("DriveItemId"),
  CONSTRAINT "CK_AP_INBOUND_SHAREPOINT_Status" CHECK (
    "Status" IN (
      'QUEUED',
      'PENDING',
      'PROCESSED',
      'FAILED',
      'INVALID_NAME',
      'IGNORED',
      'NO_DOCUMENT'
    )
  )
);

CREATE INDEX IF NOT EXISTS "IX_AP_INBOUND_SHAREPOINT_Status_LastModified"
  ON "AP_INBOUND_SHAREPOINT" ("Status", "LastModifiedAt" DESC);

CREATE INDEX IF NOT EXISTS "IX_AP_INBOUND_SHAREPOINT_DocumentId"
  ON "AP_INBOUND_SHAREPOINT" ("DocumentId");
